/* ===== Worker + Durable Object phòng bầu trời chung: bọc SkyRoom, WebSocket hibernation ===== */
import { multiParams as P } from '../../../src/explore/multi/params';
import { SkyRoom } from './room';
import type { Out } from './room';

interface Env { SKY: DurableObjectNamespace; ALLOWED_ORIGINS: string }
interface Att { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive'; ch?: number }   // seen: giờ có tin cuối của người giữ slot, ghi thưa (mỗi heartbeatMs) để sống sót qua hibernation; kind: 'walk' = slot nằm ở nhóm đi dạo, 'drive' = nhóm lái xe, không có = nhóm bay; ch: nhân vật người đi dạo chọn (chỉ ghi khi khác 0)

// So khớp scheme + hostname, bỏ cổng
function originKey(o: string): string | null {
  try { const u = new URL(o); return u.protocol + '//' + u.hostname; } catch { return null; }
}

// Mục cho phép có '*' (vd. bản xem trước PR của Netlify): '*' chỉ khớp một đoạn chữ thường/số, không có '.' hay '-'
function originAllowed(key: string, pattern: string): boolean {
  const p = originKey(pattern.replace(/\*/g, 'x'));
  if (!p) return false;
  if (!pattern.includes('*')) return p === key;
  const re = new RegExp('^' + pattern.trim().split('*').map(s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('[a-z0-9]+') + '$');
  return re.test(key);
}

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);
    if (url.pathname !== '/sky') return new Response('Not found', { status: 404 });
    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
    const key = originKey(req.headers.get('Origin') || '');
    if (!key || !env.ALLOWED_ORIGINS.split(',').some(s => originAllowed(key, s.trim()))) return new Response('Forbidden', { status: 403 });
    return env.SKY.get(env.SKY.idFromName('sky')).fetch(req);
  }
};

export class SkyObject implements DurableObject {
  private room = new SkyRoom();
  private names = new Map<number, string>();
  private walkNames = new Map<number, string>();   // tên người đi dạo theo slot, lấy từ walkers của lobby
  private driveNames = new Map<number, string>();  // tên người lái theo slot, lấy từ drivers của lobby
  private armed: boolean | null = null;   // đã đặt alarm chưa; null = chưa biết (vừa dựng hoặc vừa thức dậy): hỏi storage một lần

  constructor(private state: DurableObjectState, _env: Env) {
    // Đánh thức sau hibernation: dựng lại phòng từ attachment của từng socket
    const now = Date.now();
    const list: Att[] = [];
    for (const ws of this.state.getWebSockets()) {
      const a = ws.deserializeAttachment() as Att | null;
      if (!a) continue;
      this.room.connect(a.id, now);
      if (a.slot >= 0) list.push(a);
    }
    this.room.restore(list, now);
  }

  async fetch(_req: Request): Promise<Response> {
    const pair = new WebSocketPair();
    const [client, server] = [pair[0], pair[1]];
    const id = crypto.randomUUID();
    this.state.acceptWebSocket(server);
    server.serializeAttachment({ id, slot: -1, name: '' } as Att);
    const outs = this.room.connect(id, Date.now());
    if (outs === null) { server.close(1013, 'full'); return new Response(null, { status: 503 }); }
    this.dispatch(outs);
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
    const a = ws.deserializeAttachment() as Att | null;
    if (!a || typeof data !== 'string') return;
    this.dispatch(this.room.message(a.id, data, Date.now()));
    await this.armAlarm();
  }

  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }

  async alarm(): Promise<void> {
    this.armed = false;   // alarm đã chạy thì không còn alarm nào chờ
    this.dispatch(this.room.sweep(Date.now()));
    await this.armAlarm();
  }

  private drop(ws: WebSocket): void {
    const a = ws.deserializeAttachment() as Att | null;
    if (a) this.dispatch(this.room.disconnect(a.id));
  }

  // Gửi tin ra socket rồi ghi lại slot/tên/seen mới vào attachment (để sống sót qua hibernation); seen chỉ ghi khi cũ hơn heartbeatMs
  private dispatch(outs: Out[]): void {
    const socks = this.state.getWebSockets();
    for (const o of outs) {
      const text = JSON.stringify(o.msg);
      for (const ws of socks) {
        const a = ws.deserializeAttachment() as Att | null;
        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
        try { ws.send(text); } catch { /* socket đã đóng */ }
      }
      if (o.msg.t === 'lobby') {
        this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
        this.walkNames = new Map((o.msg.walkers ?? []).map(f => [f.slot, f.name]));
        this.driveNames = new Map((o.msg.drivers ?? []).map(f => [f.slot, f.name]));
      }
    }
    for (const ws of socks) {
      const a = ws.deserializeAttachment() as Att | null;
      if (!a) continue;
      const kind = this.room.kindOf(a.id);
      const walk = kind === 'walk', drive = kind === 'drive';
      const slot = walk ? this.room.walkSlotOf(a.id) : drive ? this.room.driveSlotOf(a.id) : this.room.slotOf(a.id);
      const name = slot >= 0 ? ((walk ? this.walkNames : drive ? this.driveNames : this.names).get(slot) ?? a.name) : '';
      const seen = this.room.seenOf(a.id);
      const stale = slot >= 0 && !(seen - (a.seen ?? -Infinity) < P.heartbeatMs);
      const k = walk ? 'walk' : drive ? 'drive' : undefined;   // loại ghi trong attachment; người bay không ghi (attachment như bản cũ)
      const ch = this.room.chOf(a.id);
      if (slot !== a.slot || name !== a.name || a.kind !== k || (a.ch ?? 0) !== ch || stale) {
        const next: Att = slot < 0 ? { id: a.id, slot, name } : k ? { id: a.id, slot, name, seen, kind: k } : { id: a.id, slot, name, seen };
        if (ch) next.ch = ch;
        ws.serializeAttachment(next);
      }
    }
  }

  private async armAlarm(): Promise<void> {
    if (!this.room.hasFlyers() || this.armed) return;
    if (this.armed === null && (await this.state.storage.getAlarm()) !== null) { this.armed = true; return; }
    this.armed = true;
    try { await this.state.storage.setAlarm(Date.now() + P.sweepMs); } catch (e) { this.armed = false; throw e; }
  }
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
import type { Flyer, Kind, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
  mySlot = -1;
  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  ch = 0;             // nhân vật đi dạo mình chọn (0 nam, 1 nữ); gửi kèm join kind 'walk' (sảnh và lời mời đều qua join())
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  onWalkPos: (w: number[][]) => void = () => {};
  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}

  /* Danh sách cùng loại với mình */
  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }

  /* Số chỗ của nhóm cùng loại */
  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
  join(name: string): void {
    this.name = name; this.notice = '';
    if (this.kind === 'drive' && this.first) return;
    this.t?.send(this.kind === 'fly' ? { t: 'join', name } : this.kind === 'walk' ? { t: 'join', name, kind: 'walk', ch: this.ch } : { t: 'join', name, kind: this.kind });
  }

  // Rời chỗ (do rời máy): trả slot, chuyển sang xem, báo 'released' như khi máy chủ thu hồi chỗ
  leave(): void {
    if (this.phase !== 'flying') return;
    this.t?.send({ t: 'leave' });
    this.notice = 'released'; this.toWatching();
    this.onChange();
  }

  // ts: giờ gửi (ms, đồng hồ của khách này) để người xem đặt mẫu theo trục giờ người gửi
  sendPos(x: number, y: number, z: number, yaw: number, bank: number, ts: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, bank, ts });
  }

  // Người đi dạo: pose (0 đứng, 1 đi, 2 chạy, 3 rơi (bản cũ: nhảy), 4 chụp ảnh) thay cho bank
  sendWalk(x: number, y: number, z: number, yaw: number, pose: number, ts: number): void {
    if (this.phase === 'flying') this.t?.send({ t: 'pos', x, y, z, yaw, pose, ts });
  }

  // Người lái: v tốc độ có dấu (m/s), st góc lái (rad) thay cho bank / pose; ts giờ gửi (ms, đồng hồ khách này), không truyền thì lấy performance.now()
  sendDrive(p: { x: number; y: number; z: number; yaw: number; v: number; st: number; ts?: number }): void {
    if (this.phase !== 'flying') return;
    const ts = typeof p.ts === 'number' ? p.ts : Math.round(performance.now());
    this.t?.send({ t: 'pos', x: p.x, y: p.y, z: p.z, yaw: p.yaw, v: p.v, st: p.st, ts });
  }

  heartbeat(): void {
    if (this.phase === 'flying') this.t?.send({ t: 'hb' });
  }

  dispose(): void {
    this.disposed = true;
    this.t?.close(); this.t = null;
  }

  private toWatching(): void {
    this.phase = 'watching'; this.mySlot = -1;
    if (this.kind === 'walk') this.walkers = this.walkers.filter(f => f.slot !== this.mySlotWas);
    else if (this.kind === 'drive') this.drivers = this.drivers.filter(f => f.slot !== this.mySlotWas);
    else this.flyers = this.flyers.filter(f => f.slot !== this.mySlotWas);
    this.fixWatched();
  }
  private mySlotWas = -1;

  // Giữ watched nếu người đó còn; không thì chọn ngẫu nhiên người khác (cùng loại)
  private fixWatched(): void {
    const ids = this.peers.map(f => f.slot);
    if (this.phase === 'watching') {
      if (!ids.includes(this.watched)) this.watched = ids.length ? ids[this.pick(ids.length)] : -1;
      this.invite = ids.length < this.cap;
    } else { this.watched = -1; this.invite = false; }
  }

  private lost(): void {
    if (this.disposed) return;
    this.phase = 'solo'; this.notice = 'lost';
    this.flyers = []; this.walkers = []; this.drivers = []; this.mySlot = -1; this.watched = -1; this.invite = false;
    this.t = null; this.onChange();
  }

  /* Máy chủ cũ (lobby đầu không có walkers / drivers) không biết chỗ đi dạo / lái xe: đóng kết nối, đi / lái một mình như khi không kết nối được */
  private offline(): void {
    const t = this.t;
    this.t = null;
    if (t) { t.onClose = () => {}; t.onMessage = () => {}; t.close(); }
    this.phase = 'solo'; this.notice = 'offline';
    this.flyers = []; this.walkers = []; this.drivers = [];
    this.onChange();
  }

  private recv(m: ServerMsg): void {
    if (this.disposed) return;
    switch (m.t) {
      case 'lobby':
        if (this.first && this.kind === 'walk' && !Array.isArray(m.walkers)) { this.first = false; this.offline(); return; }
        if (this.first && this.kind === 'drive' && !Array.isArray(m.drivers)) { this.first = false; this.offline(); return; }
        this.flyers = m.flyers;
        this.walkers = Array.isArray(m.walkers) ? m.walkers : [];
        this.drivers = Array.isArray(m.drivers) ? m.drivers : [];
        if (this.first) {
          this.first = false;
          if (this.peers.length >= this.cap) this.phase = 'watching';
          else this.phase = 'lobby';
        }
        // đang giữ chỗ: danh sách chỉ để hiển thị
        this.fixWatched();
        break;
      case 'joined':
        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
        this.fixWatched();
        break;
      case 'rejected':
        if (m.why === 'name') this.notice = 'nameBad';
        else {
          this.notice = 'late';   // giành trước khi đang xem, hoặc ngay ở sảnh (chỗ cuối vừa có người lúc bấm): đều báo lý do
          this.phase = 'watching';
          this.fixWatched();
        }
        break;
      case 'pos':
        this.onPos(m.f);
        if (Array.isArray(m.w)) this.onWalkPos(m.w);
        if (Array.isArray(m.d)) this.peersDrive(m.d);
        return;
      case 'released':
        if (this.phase === 'flying') { this.notice = 'released'; this.toWatching(); }
        break;
    }
    this.onChange();
  }
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: điều phối phía khách =====
   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), stAvatars (người đi dạo khác), exDrivers (xe người khác), nhãn tên và danh sách người chơi.
   Cả ba loại thấy nhau; mỗi phiên chỉ giữ một loại chỗ (session.kind). drCars.group chỉ ở trong cảnh khi có xe (exDrivers.onCars), không thì 0 lệnh vẽ.
   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
import { scene, camera } from '../../core/renderer';
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exConnect } from './client';
import { MultiSession } from './session';
import { exRemotes } from './remote';
import { exLabelsUpdate, exLabelsClear } from './labels';
import { ExIdle } from './idle';
import { stAvatars } from '../stroll/avatars';
import { stChar } from '../stroll/char';
import { exDrivers } from './remoteDrive';
import { drCars } from '../drive/cars';
import type { Kind } from './protocol';
import type { GliderState } from '../flight';
import type { StState } from '../stroll/motion';
import type { DrState } from '../drive/motion';

const M = CONFIG.explore.multi;
let session: MultiSession | null = null;
let sentAt = -1e9;
let rosterKey = '';
let idle: ExIdle | null = null;
let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi

/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
function idleParams(): [number, number] {
  const q = new URLSearchParams(location.search);
  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
}

function idleShow(text: string): void {
  const el = document.getElementById('exMpIdle');
  if (!el || text === idleShown) return;
  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
  idleShown = text;
  el.textContent = text;
  el.hidden = text === '';
}

function idleTick(): void {
  if (!session || !idle || session.phase !== 'flying') return;
  const now = performance.now();
  const st = idle.tick(now);
  if (st === 'ok') idleShow('');
  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
}

function idleStart(): void {
  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
  const [a, b] = idleParams();
  idle = new ExIdle(a, b); idle.reset(performance.now());
  idleShown = '';
  idleTimer = window.setInterval(idleTick, M.idleTickMs);
  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
}

function idleStop(): void {
  clearInterval(idleTimer); clearInterval(beatTimer);
  idleTimer = beatTimer = 0; idle = null;
  idleShow('');
}

/* Danh sách người chơi ở góc màn hình: đầu "Lái xe n/5 · Đi dạo n/5 · Bay n/5", rồi nhóm người lái (chấm thoi), người đi dạo (chấm vuông) và người bay (chấm tròn),
   mỗi người một dòng có chấm màu theo slot; dòng của mình đậm. Dùng textContent */
function renderRoster(): void {
  const box = document.getElementById('exMpRoster');
  if (!box) return;
  const flyers = session ? session.flyers : [], walkers = session ? session.walkers : [], drivers = session ? session.drivers : [];
  const head = t('drRosterAll', { d: drivers.length, w: walkers.length, f: flyers.length });
  const kind = session ? session.kind : 'fly', mine = session ? session.mySlot : -1;
  const key = drivers.map(f => f.slot + ':' + f.name).join('|') + '#' + walkers.map(f => f.slot + ':' + f.name).join('|') + '#' + flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + kind + mine + '#' + head;
  if (key === rosterKey) return;
  rosterKey = key;
  box.hidden = !session || session.phase === 'solo';
  box.textContent = '';
  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
  const group = (list: typeof flyers, k: 'fly' | 'walk' | 'drive') => {
    for (const f of list) {
      const row = document.createElement('div'); row.className = 'ex-mp-row' + (k === 'walk' ? ' walk' : k === 'drive' ? ' drive' : '') + (k === kind && f.slot === mine ? ' me' : '');
      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
      const nm = document.createElement('span'); nm.textContent = f.name;
      row.append(dot, nm); box.appendChild(row);
    }
  };
  group(drivers, 'drive'); group(walkers, 'walk'); group(flyers, 'fly');
}

/* Người đi dạo hiện cho cả người bay: dựng nhóm nhân vật (lười) lần đầu phòng có người đi dạo; mô hình có xương nạp khi slot đầu tiên hiện */
function stEnsureAvatars(): void {
  const mesh = stAvatars.build();
  if (!mesh.parent) scene.add(mesh);
}

/* Xe người lái hiện cho cả người bay và người đi dạo: gắn / gỡ nhóm xe theo số xe (không có xe thì không ở trong cảnh) */
exDrivers.onCars = (n: number): void => {
  const g = drCars.group;
  if (n > 0) { if (!g.parent) scene.add(g); } else if (g.parent) g.removeFromParent();
};

export const exMulti = {
  /* Địa chỉ máy chủ: có ?test thì ?multi= nếu có, không có thì rỗng (không mở mạng); không có ?test thì luôn là địa chỉ cấu hình (người ngoài không đổi được máy chủ qua URL) */
  url(): string {
    const q = new URLSearchParams(location.search);
    if (!q.has('test')) return M.url;
    return q.get('multi') ?? '';
  },
  get session(): MultiSession | null { return session; },
  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test

  /* Mở phiên loại kind ('fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe); onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
  begin(onReady: () => void, kind: Kind = 'fly'): boolean {
    const url = exMulti.url();
    if (!url || session) return false;
    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs), undefined, kind);
    if (kind === 'walk') s.ch = stChar.get();   // nhân vật đã chọn lần trước; sảnh đổi thì ghi lại (lobby.ts)
    let ready = false;
    s.onPos = f => exRemotes.onPos(f, performance.now());
    s.onWalkPos = w => stAvatars.onPos(w, performance.now());
    s.peersDrive = d => exDrivers.onPos(d, performance.now());
    s.onChange = () => {
      exRemotes.sync(s.flyers, s.kind === 'fly' ? s.mySlot : -1);   // slot đi dạo và slot bay là hai nhóm: số slot của mình chỉ loại trừ trong nhóm của mình
      if (s.walkers.length || stAvatars.mesh) { stEnsureAvatars(); stAvatars.sync(s.walkers, s.kind === 'walk' ? s.mySlot : -1); }
      exDrivers.sync(s.drivers, s.kind === 'drive' ? s.mySlot : -1);
      if (s.phase === 'solo') exLabelsClear();
      renderRoster();
      if (s.phase === 'flying') idleStart(); else idleStop();
      exMulti.onChange();
      if (!ready) { ready = true; onReady(); }
    };
    s.open();
    return true;
  },

  /* Đóng phiên (Quay lại / Esc ở sảnh, hoặc chọn Bay một mình khi có máy chủ): đóng WebSocket, ẩn dù người khác, nhãn, danh sách; begin() mở lại được */
  end(): void {
    if (!session) return;
    session.dispose(); session = null;
    exMulti.onChange = () => {};
    idleStop(); exRemotes.clear(); stAvatars.clear(); exDrivers.clear(); exLabelsClear();
    rosterKey = ''; renderRoster();
  },

  /* Mỗi khung (bay, đi dạo, lái xe hoặc xem): dù người khác, người đi dạo khác, xe người khác, nhãn; đang bay thì gửi vị trí sendHz lần/s (state = null: không gửi) */
  update(dt: number, nowMs: number, state: GliderState | null): void {
    if (!session) return;
    exRemotes.update(nowMs);
    if (stAvatars.mesh) stAvatars.update(nowMs);   // người đi dạo khác, kể cả khi mình bay dù
    exDrivers.update(nowMs, dt);   // xe người khác, kể cả khi mình bay dù hoặc đi dạo
    exLabelsUpdate(camera, exRemotes, nowMs, stAvatars, exDrivers);
    if (state && session.kind === 'fly' && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
      sentAt = nowMs;
      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank), Math.round(nowMs));
    }
  },

  /* Mỗi khung khi đi dạo có chỗ: gửi vị trí + dáng sendHz lần/s (s = null: không gửi) */
  updateWalk(nowMs: number, s: StState | null): void {
    if (!session || !s || session.kind !== 'walk' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
    sentAt = nowMs;
    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
    session.sendWalk(r(s.x), r(s.y), r(s.z), a(s.yaw), s.pose, Math.round(nowMs));
  },

  /* Mỗi khung khi lái xe có chỗ: gửi vị trí + vận tốc + góc lái sendHz lần/s (s = null: không gửi). Cả lúc đang sơ tán khỏi nhịp quay Cầu sông Hàn */
  updateDrive(nowMs: number, s: DrState | null): void {
    if (!session || !s || session.kind !== 'drive' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
    sentAt = nowMs;
    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
    session.sendDrive({ x: r(s.x), y: r(s.y), z: r(s.z), yaw: a(s.yaw), v: r(s.v), st: a(s.steer), ts: Math.round(nowMs) });
  },

  /* Người chơi vừa bấm phím điều khiển: đếm lại thời gian rời máy */
  activity(): void {
    if (!idle) return;
    idle.activity(performance.now());
    idleShow('');
  },

  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
  watchState(): GliderState | null {
    return session && session.kind === 'fly' && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
  },

  /* Trạng thái người đi dạo đang xem (hết chỗ đi dạo); null nếu không xem ai */
  watchWalker(): { x: number; y: number; z: number; yaw: number; pose: number } | null {
    return session && session.kind === 'walk' && session.phase === 'watching' && session.watched >= 0 ? stAvatars.slotState(session.watched) : null;
  },

  /* Trạng thái xe đang xem (hết chỗ lái); null nếu không xem ai hoặc xe chưa có mẫu */
  watchDriver(): { x: number; y: number; z: number; yaw: number; v: number } | null {
    return session && session.kind === 'drive' && session.phase === 'watching' && session.watched >= 0 ? exDrivers.slotState(session.watched) : null;
  }
};

onLang(() => { rosterKey = ''; renderRoster(); });

