/* ===== Lái xe nhiều người: xe của người lái cùng =====
   Mỗi slot một xe (drCars, màu multiParams.colors[slot]). Gói d = [slot, x, y, z, yaw, v, st, giờ gửi] nhận 5 lần/s; vị trí + góc lái (st) nội suy bằng một ExTrack,
   tốc độ v bằng ExTrack thứ hai (v đặt ở trường x; hai track nhận cùng giờ gửi nên cùng độ lệch giờ), lấy mẫu chậm interpSends chu kỳ như dù lượn.
   Từ mẫu nội suy: bánh quay theo tích phân v / bán kính bánh, đèn phanh khi |v| giảm nhanh hơn CONFIG.drive.remote.brakeDecel, độ nghiêng dọc suy từ cao độ
   giữa hai khung (làm mượt, kẹp) để xe bám dốc cầu / hầm. Xe người khác không tham gia va chạm.
   Slot đổi chủ thì gỡ xe cũ; xe mới ẩn tới khi có mẫu đầu. Xe của mình (selfSlot) cũng nằm trong drCars: setSelf đặt slot đó, người dùng drive/index.ts tự place.
   Module không đụng cảnh: onCars(n) báo số xe để multi/index.ts gắn / gỡ drCars.group (không có xe thì group không ở trong cảnh, 0 lệnh vẽ). Không cấp phát mỗi khung (D-018). */
import { CONFIG } from '../../config';
import { drCars } from '../drive/cars';
import type { DrPlace } from '../drive/car';
import type { DrMapDot } from '../drive/hud';
import { ExTrack, type ExPose } from './interp';
import type { Flyer } from './protocol';

const M = CONFIG.explore.multi, R = CONFIG.drive.remote, RW = CONFIG.drive.car.wheelDia / 2;

export interface ExDriverState { x: number; y: number; z: number; yaw: number; v: number }

interface DSlot {
  name: string | null;        // null = slot trống (hoặc của mình)
  tr: ExTrack;                // x, y, z, yaw, bank = góc lái st
  tv: ExTrack;                // tốc độ có dấu v (đặt ở trường x)
  pose: ExPose;               // đệm lấy mẫu của tr
  vp: ExPose;                 // đệm lấy mẫu của tv
  place: DrPlace;             // tư thế trả cho drCars.place
  state: ExDriverState;       // trả cho nhãn tên, bản đồ nhỏ, camera xem
  dot: DrMapDot;              // chấm trên bản đồ nhỏ
  live: boolean;              // đã có mẫu và đang hiện
  px: number; py: number; pz: number;   // vị trí lúc đo độ nghiêng gần nhất
  absV: number;               // |v| khung trước (suy đèn phanh)
  lastMs: number;             // giờ khách nhận gói gần nhất (ms), để biết mẫu cuối đã cũ (gói ngừng tới thì v về 0, bánh thôi quay)
}

const slots: DSlot[] = Array.from({ length: M.drive.slots }, (_, i) => ({
  name: null, tr: new ExTrack(), tv: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 }, vp: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
  place: { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, steer: 0, wheel: 0, braking: false },
  state: { x: 0, y: 0, z: 0, yaw: 0, v: 0 }, dot: { x: 0, z: 0, color: M.colors[i % M.colors.length] },
  live: false, px: 0, py: 0, pz: 0, absV: 0, lastMs: 0
}));
const _a: number[] = [0, 0, 0, 0, 0, 0, 0];   // [slot, x, y, z, yaw, st, giờ gửi] cho tr
const _b: number[] = [0, 0, 0, 0, 0, 0, 0];   // [slot, v, 0, 0, 0, 0, giờ gửi] cho tv
const _dots: DrMapDot[] = [];
let selfSlot = -1;          // slot xe của mình trong drCars (-1 = không có xe của mình)
let me = -1;                // slot của mình trong nhóm lái (không lấy xe người khác ở slot này)

function hide(s: DSlot): void { s.tr.reset(); s.tv.reset(); s.live = false; s.absV = 0; }

/* Dựng lại danh sách xe của drCars (xe của mình + xe người khác) và báo số xe */
function refresh(): void {
  const list: { slot: number }[] = [];
  if (selfSlot >= 0) list.push({ slot: selfSlot });
  for (let i = 0; i < slots.length; i++) if (slots[i].name !== null && i !== selfSlot) list.push({ slot: i });
  drCars.sync(list);
  for (let i = 0; i < slots.length; i++) if (slots[i].name !== null && i !== selfSlot) drCars.show(i, slots[i].live);
  exDrivers.onCars(list.length);
}

export const exDrivers = {
  onCars: (_n: number): void => {},   // multi/index.ts đặt: gắn / gỡ drCars.group theo số xe

  /* Danh sách người lái đổi (sảnh, vào, ra): dựng xe slot mới, gỡ xe slot đổi chủ hoặc trống. mySlot: slot của mình nếu mình đang lái, ngược lại -1 */
  sync(drivers: Flyer[], mySlot: number): void {
    me = mySlot;
    for (let i = 0; i < slots.length; i++) {
      const s = slots[i];
      let name: string | null = null;
      if (i !== mySlot) for (const f of drivers) if (f.slot === i) { name = f.name; break; }
      if (name !== s.name) {
        if (i !== selfSlot) drCars.remove(i);   // chủ cũ đi hoặc đổi tên: xe mới không trượt từ chỗ người cũ
        s.name = name; hide(s);
      }
    }
    refresh();
  },

  /* Xe của mình nằm ở slot này trong drCars (-1: không có, ví dụ đang xem); xe của mình do drive/index.ts đặt tư thế */
  setSelf(slot: number): void {
    if (slot === selfSlot) return;
    if (selfSlot >= 0) drCars.remove(selfSlot);
    selfSlot = slot;
    if (slot >= 0 && slot < slots.length && slots[slot].name !== null) { slots[slot].name = null; hide(slots[slot]); }   // slot của mình không thể còn tên người khác
    refresh();
  },

  /* Gói d: mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]; chỉ nhận slot đã biết chủ và không phải của mình */
  onPos(d: number[][], nowMs: number): void {
    for (const e of d) {
      const i = e[0], s = slots[i];
      if (!s || i === me || i === selfSlot || s.name === null) continue;
      _a[0] = _b[0] = i;
      _a[1] = e[1]; _a[2] = e[2]; _a[3] = e[3]; _a[4] = e[4]; _a[5] = e[6]; _a[6] = e[7];
      _b[1] = e[5]; _b[6] = e[7];
      s.tr.feed(_a, nowMs, M); s.tv.feed(_b, nowMs, M); s.lastMs = nowMs;
    }
  },

  /* Mỗi khung: lấy mẫu, quay bánh, đèn phanh, độ nghiêng, đặt xe */
  update(nowMs: number, dt: number): void {
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (let i = 0; i < slots.length; i++) {
      const s = slots[i];
      if (s.name === null || i === selfSlot) continue;
      if (!s.tr.sample(t, s.pose) || !s.tv.sample(t, s.vp)) continue;
      const p = s.pose, v = nowMs - s.lastMs > R.staleMs ? 0 : s.vp.x, pl = s.place, av = Math.abs(v);
      if (!s.live) {
        s.live = true; s.px = p.x; s.py = p.y; s.pz = p.z; pl.pitch = 0; pl.wheel = 0; s.absV = av;
        drCars.show(i, true);
      } else if (dt > 0) {
        const dx = p.x - s.px, dz = p.z - s.pz, dxz = Math.hypot(dx, dz);
        if (dxz >= R.pitchMinMove) {   // dời đủ xa mới đo độ nghiêng; chưa đủ thì cộng dồn quãng
          const tgt = Math.max(-R.pitchMax, Math.min(R.pitchMax, Math.atan2((p.y - s.py) * (v < 0 ? -1 : 1), dxz)));
          pl.pitch += (tgt - pl.pitch) * (1 - Math.exp(-dt / R.pitchTau));
          s.px = p.x; s.py = p.y; s.pz = p.z;
        }
        pl.wheel += v * dt / RW;
      }
      pl.braking = dt > 0 && (s.absV - av) / dt > R.brakeDecel;
      s.absV = av;
      pl.x = p.x; pl.y = p.y; pl.z = p.z; pl.yaw = p.yaw; pl.steer = p.bank;
      drCars.place(i, pl);
      const st = s.state; st.x = p.x; st.y = p.y; st.z = p.z; st.yaw = p.yaw; st.v = v;
    }
  },

  /* Trạng thái đã nội suy của xe ở slot (cho nhãn tên, camera xem, bản đồ nhỏ); null nếu chưa có hoặc slot trống */
  slotState(slot: number): ExDriverState | null {
    const s = slots[slot];
    return s && s.name !== null && s.live ? s.state : null;
  },
  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },

  /* Chấm xe người khác cho bản đồ nhỏ (mảng và phần tử tái dùng, chỉ xe đã hiện); except: trạng thái xe đang được xem (đã có mũi tên của bản đồ nên bỏ chấm) */
  dots(except?: ExDriverState | null): DrMapDot[] {
    let n = 0;
    for (const s of slots) {
      if (s.name === null || !s.live || s.state === except) continue;
      const d = s.dot; d.x = s.state.x; d.z = s.state.z;
      _dots[n++] = d;
    }
    _dots.length = n;
    return _dots;
  },

  /* Rời phòng / thoát chế độ: ẩn hết, quên tên và xe của mình */
  clear(): void {
    me = -1;
    for (let i = 0; i < slots.length; i++) { const s = slots[i]; if (s.name !== null) { drCars.remove(i); s.name = null; } hide(s); }
    if (selfSlot >= 0) drCars.remove(selfSlot);
    selfSlot = -1;
    refresh();
  }
};
/* ===== Dù lượn, đi dạo và lái xe nhiều người: nhãn tên nổi cạnh người chơi khác =====
   Một div cho mỗi slot bay, mỗi slot đi dạo và mỗi slot lái xe trong #exMpLabels (theo thứ tự đó). Dù: điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù);
   người đi dạo: cao hơn chân CONFIG.stroll.labelAbove m (trên đầu); xe: trên nóc, cao hơn mặt đường car.height + drive.remote.labelAbove m. Ẩn khi sau camera hoặc slot chưa hiện; nhân vật của mình không có nhãn.
   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import type { exRemotes } from './remote';
import type { stAvatars } from '../stroll/avatars';
import type { exDrivers } from './remoteDrive';

const M = CONFIG.explore.multi, NW = M.stroll.slots, ND = M.drive.slots, CAR_TOP = CONFIG.drive.car.height + CONFIG.drive.remote.labelAbove;
interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
let labs: Lab[] | null = null;   // M.slots nhãn dù, NW nhãn người đi dạo rồi ND nhãn xe
const _v = new THREE.Vector3();

function init(): Lab[] | null {
  const box = document.getElementById('exMpLabels');
  if (!box) return null;
  return Array.from({ length: M.slots + NW + ND }, () => {
    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
  });
}

// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;

/* Đặt một nhãn tại điểm (x, y, z) với tên name; trả true nếu hiện */
function place(L: Lab, camera: THREE.Camera, x: number, y: number, z: number, name: string, nowMs: number, w: number, h: number): boolean {
  _v.set(x, y, z).applyMatrix4(camera.matrixWorldInverse);
  if (-_v.z <= 0.1) return false;   // sau camera
  _v.applyMatrix4(camera.projectionMatrix);
  const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
  if (px <= -80 || px >= w + 80 || py <= -40 || py >= h + 40) return false;
  if (nowMs - L.tMs >= 200) {
    L.tMs = nowMs;
    const txt = `${name} · ${dist(Math.hypot(x - camera.position.x, y - camera.position.y, z - camera.position.z))}`;
    if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
  }
  if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
  return true;
}

export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number, walkers?: typeof stAvatars, drivers?: typeof exDrivers): void {
  if (!labs && !(labs = init())) return;
  const w = window.innerWidth, h = window.innerHeight;
  for (let i = 0; i < M.slots; i++) {
    const L = labs[i], st = remotes.slotState(i);
    const vis = !!st && place(L, camera, st.pos.x, st.pos.y - M.labelBelow, st.pos.z, remotes.name(i), nowMs, w, h);
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
  for (let i = 0; i < NW; i++) {
    const L = labs[M.slots + i], st = walkers && i !== walkers.self ? walkers.slotState(i) : null, nm = st ? walkers!.name(i) : null;
    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + CONFIG.stroll.labelAbove, st.z, nm, nowMs, w, h);
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
  for (let i = 0; i < ND; i++) {
    const L = labs[M.slots + NW + i], st = drivers ? drivers.slotState(i) : null, nm = st ? drivers!.name(i) : null;   // xe của mình không có trong exDrivers (slotState null)
    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + CAR_TOP, st.z, nm, nowMs, w, h);
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
}

/* Ẩn hết nhãn (rời phòng) */
export function exLabelsClear(): void {
  if (!labs) return;
  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: bước chọn slot và nhập tên (trong hộp thoại #chooser) =====
   Hiện sau khi bấm thẻ Dù lượn (hoặc Đi dạo) lúc có máy chủ: 5 chấm + "Còn N trên 5 chỗ", tên những người cùng loại (session.peers), ô tên, nút Bay ngay / Đi dạo ngay / Lái ngay.
   Chữ chọn theo session.kind (multi/keys.ts: exMp* cho dù lượn, st* cho đi dạo, dr* cho lái xe); tên nhớ dùng chung cho ba loại.
   Sảnh đi dạo có thêm ô chọn nhân vật nam / nữ (#stCharPick, cả khi ngoại tuyến): nhớ ở stChar, ghi vào session.ch để join gửi kèm, nạp trước mô hình vừa chọn.
   Cập nhật trực tiếp theo MultiSession; tên người khác chỉ ghi bằng textContent. Tên của mình nhớ ở localStorage.
   Pha lobby: cho nhập tên và giành chỗ. Pha solo (không kết nối được): báo ngoại tuyến. Nút Bay một mình hiện ở cả hai pha (đóng phiên rồi bay một mình).
   Pha flying: gọi onFly. Pha watching (hết chỗ): gọi onWatch (chế độ xem do Task 7 làm).
   Nút Quay lại hoặc Esc: đóng phiên (đóng WebSocket), trả lại các thẻ, tiêu đề và aria-labelledby, gọi onBack để chọn lại.
   Trình nghe gắn một lần cho cả trang và đọc sảnh đang mở (cur), nên vào sảnh nhiều lần không nhân đôi. */
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exMulti } from './index';
import { exSanitizeName } from './protocol';
import { exMpKeys, exMpSlots } from './keys';
import type { MultiSession } from './session';
import { stChar } from '../stroll/char';
import { stAvatars } from '../stroll/avatars';

export interface LobbyCallbacks { onFly: () => void; onWatch: () => void; onSolo: () => void; onBack: () => void }

const M = CONFIG.explore.multi;
const NAME_KEY = 'exMpName';
const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

export function loadName(): string { try { return localStorage.getItem(NAME_KEY) || ''; } catch { return ''; } }
export function saveName(n: string): void { try { localStorage.setItem(NAME_KEY, n); } catch { /* bộ nhớ trình duyệt bị chặn */ } }

let listKey = '';
let bound = false;
let cur: { session: MultiSession; cb: LobbyCallbacks } | null = null;   // sảnh đang mở; null = đã đóng (vào bay, xem, bay một mình, quay lại)

/* Đóng sảnh rồi gọi f (một lần) */
function finish(f: () => void): void {
  if (!cur) return;
  cur = null; exMulti.onChange = () => {};
  f();
}

/* Trả hộp thoại về các thẻ: hiện tiêu đề, gắn lại aria-labelledby */
function restoreCards(): void {
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement;
  root.hidden = true;
  box.querySelector<HTMLElement>('.ex-cards')!.hidden = false;
  $('exTitle').hidden = false;
  box.setAttribute('aria-labelledby', 'exTitle');
}

/* Quay lại / Esc: đóng phiên và về các thẻ */
function back(): void {
  const c = cur; if (!c) return;
  finish(() => { exMulti.end(); restoreCards(); c.cb.onBack(); });
}

/* Bay một mình (có hay không có máy chủ): đóng phiên để không gửi/nhận gì */
function solo(): void {
  const c = cur; if (!c) return;
  finish(() => { exMulti.end(); c.cb.onSolo(); });
}

/* Ghi chữ theo khóa và nhớ khóa ở data-i18n (đổi ngôn ngữ thì i18n dịch lại đúng khóa của loại sảnh đang mở) */
function setKey(id: string, key: string): void {
  const el = $(id);
  if (el.dataset.i18n !== key) el.dataset.i18n = key;
  const v = t(key);
  if (el.textContent !== v) el.textContent = v;
}

function render(): void {
  if (!cur) return;
  const session = cur.session, cb = cur.cb, K = exMpKeys(session.kind);
  const fly = $<HTMLButtonElement>('exMpFly'), soloBtn = $<HTMLButtonElement>('exMpSolo'), input = $<HTMLInputElement>('exMpNameIn');
  const ph = session.phase;
  if (ph === 'flying') { finish(cb.onFly); return; }
  if (ph === 'watching') { finish(cb.onWatch); return; }
  /* Chữ theo loại sảnh: bầu trời (dù lượn) hoặc sông Hàn (đi dạo, lái xe) */
  setKey('exMpSky', K.sky);
  setKey('exMpFly', K.go);
  setKey('exMpSolo', K.solo);
  setKey('exMpOffline', K.offline);
  /* Chọn nhân vật: chỉ sảnh đi dạo; hiện cả khi ngoại tuyến (đi một mình vẫn theo nhân vật đã chọn) */
  const pick = $('stCharPick'), ch = stChar.get();
  pick.hidden = session.kind !== 'walk';
  pick.querySelectorAll<HTMLElement>('button[data-ch]').forEach((b) => {
    const on = Number(b.dataset.ch) === ch;
    if ((b.getAttribute('aria-checked') === 'true') !== on) b.setAttribute('aria-checked', String(on));
    b.tabIndex = on ? 0 : -1;
  });
  const offline = ph === 'solo';
  $('exMpOnline').hidden = offline;
  $('exMpOffline').hidden = !offline;
  soloBtn.classList.toggle('ex-mp-alt', !offline);   // có máy chủ: nút phụ; ngoại tuyến: nút chính
  if (offline) { if (document.activeElement !== soloBtn) soloBtn.focus({ preventScroll: true }); return; }
  const ready = ph === 'lobby';
  const peers = session.peers;
  const free = exMpSlots(session.kind) - peers.length;
  $('exMpSeats').textContent = !ready ? '…' : K.full && free <= 0 ? t(K.full) : t(K.seats, { n: free });
  $('exMpNameHint').textContent = t('exMpNameMax', { n: M.nameMax });
  const taken = new Set(peers.map(f => f.slot));
  $('exMpDots').querySelectorAll<HTMLElement>('i').forEach((d, i) => {
    d.classList.toggle('on', taken.has(i));
    d.style.background = taken.has(i) ? M.colors[i % M.colors.length] : '';
  });
  const key = session.kind + '#' + peers.map(f => f.slot + ':' + f.name).join('|');
  if (key !== listKey) {
    listKey = key;
    const list = $('exMpList'); list.textContent = '';
    for (const f of peers) {
      const row = document.createElement('div'); row.className = 'ex-mp-row';
      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
      row.append(dot, nm); list.appendChild(row);
    }
  }
  $('exMpNameBad').hidden = session.notice !== 'nameBad';
  fly.disabled = !ready || exSanitizeName(input.value) === null;
}

/* Đổi nhân vật ở sảnh: nhớ, đưa vào phiên (join gửi kèm), nạp trước mô hình */
function pickChar(ch: number): void {
  if (!cur || cur.session.kind !== 'walk') return;
  stChar.set(ch); cur.session.ch = stChar.get();
  stAvatars.preload();
  render();
}

function go(): void {
  if (!cur) return;
  const name = exSanitizeName($<HTMLInputElement>('exMpNameIn').value);
  if (name === null || cur.session.phase !== 'lobby') return;
  saveName(name);
  cur.session.join(name);
}

/* Gắn trình nghe một lần */
function bind(): void {
  if (bound) return;
  bound = true;
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
  input.addEventListener('input', () => {
    if (!cur) return;
    $('exMpNameBad').hidden = true;
    const ok = exSanitizeName(input.value);
    if (ok !== null) saveName(ok);   // nhớ ngay khi hợp lệ, tải lại trang vẫn còn
    $<HTMLButtonElement>('exMpFly').disabled = cur.session.phase !== 'lobby' || ok === null;
  });
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); go(); } });
  $('stCharPick').querySelectorAll<HTMLElement>('button[data-ch]').forEach((b) => {
    b.addEventListener('click', () => pickChar(Number(b.dataset.ch)));
    b.addEventListener('keydown', (e) => {   // nhóm radio: mũi tên đổi lựa chọn và chuyển focus
      if (!/^Arrow/.test(e.key)) return;
      e.preventDefault(); e.stopPropagation();
      const ch = Number(b.dataset.ch) === 1 ? 0 : 1;
      pickChar(ch);
      $('stCharPick').querySelector<HTMLElement>('button[data-ch="' + ch + '"]')?.focus({ preventScroll: true });
    });
  });
  $('exMpFly').addEventListener('click', go);
  $('exMpSolo').addEventListener('click', solo);
  $('exMpBack').addEventListener('click', back);
  box.addEventListener('keydown', (e) => { if (e.key === 'Escape' && cur) { e.preventDefault(); back(); } });
  onLang(() => render());
}

/* Hiện bước riêng thay cho các thẻ và gắn nó vào phiên; trả ngay (phiên đang ở pha 'connecting') */
export function exShowLobby(session: MultiSession, cb: LobbyCallbacks): void {
  bind();
  const root = $('exMpLobby'), box = root.closest('#chooser') as HTMLElement, input = $<HTMLInputElement>('exMpNameIn');
  box.querySelector<HTMLElement>('.ex-cards')!.hidden = true;
  $('exTitle').hidden = true; $('exMpLostNote').hidden = true;
  box.setAttribute('aria-labelledby', 'exMpSky');
  root.hidden = false;
  if (!input.value) input.value = loadName();
  listKey = '';
  cur = { session, cb };
  if (session.kind === 'walk') session.ch = stChar.get();
  exMulti.onChange = render;
  render();
  input.focus({ preventScroll: true });
}

