/* ===== Dù lượn, đi dạo và lái xe nhiều người: giao diện chế độ xem và các thông báo =====
   Chữ theo session.kind (multi/keys.ts): khóa exMp* (dù lượn), st* (đi dạo) hoặc dr* (lái xe); tên người đang xem lấy từ exRemotes, stAvatars hoặc exDrivers.
   #exMpWatch "Đang xem: tên", #exMpInvite (lời mời khi còn chỗ: ô tên nếu chưa có tên hợp lệ + nút vào bay), #exMpNotice (late / released / lost).
   late tự ẩn sau lateMs, released (khi xem) và lost (khi bay) tự ẩn sau noticeMs; nameBad giữ tới khi gõ tên khác.
   Không điều khiển camera hay phiên: explore/index.ts gọi exWatchShow / exWatchRender / exWatchHide và tự xử lý chuyển pha.
   Mọi tên người khác chỉ ghi bằng textContent, bọc trong cặp cô lập hướng chữ để tên RTL không làm lệch câu. */
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exSanitizeName } from './protocol';
import { exRemotes } from './remote';
import { stAvatars } from '../stroll/avatars';
import { exDrivers } from './remoteDrive';
import { exMpKeys } from './keys';
import type { Kind } from './protocol';
import { loadName, saveName } from './lobby';
import type { MultiSession } from './session';

const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

let session: MultiSession | null = null;
let bound = false;
let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
let pendingTimer = 0;
let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
let lateTimer = 0;
let relUntil = 0;          // mốc (ms) hết hạn hiện exMpReleased; 0 = chưa hiện trong lần xem này
let relTimer = 0;
let flyKey = '';           // thông báo khi bay đã hiện (không hiện lại sau khi tự ẩn)
let flyTimer = 0;
let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)

/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());

/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
export function exWatchNotice(key: string): void {
  noticeKey = key;
  const el = $('exMpNotice');
  el.textContent = key ? t(key) : '';
  el.hidden = !key;
}

function unlock(): void { pending = false; clearTimeout(pendingTimer); }

/* Hiện exMpLate thêm lateMs từ bây giờ */
function armLate(): void {
  lateUntil = performance.now() + CONFIG.explore.multi.lateMs;
  clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50);
}

function accept(): void {
  if (!session || session.phase !== 'watching' || pending) return;
  const input = $<HTMLInputElement>('exMpInviteName');
  const name = knownName() ?? exSanitizeName(input.value);
  if (name === null) return;
  pending = true; clearTimeout(pendingTimer);
  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
  exWatchRender();
}

/* Lời mời: ghi chữ theo loại và nhớ khóa ở data-i18n để đổi ngôn ngữ dịch đúng */
function inviteKeys(kind: Kind): void {
  const K = exMpKeys(kind);
  for (const [id, key] of [['exMpInviteText', K.invite], ['exMpInviteFly', K.inviteGo]]) {
    const el = $(id);
    if (el.dataset.i18n !== key) { el.dataset.i18n = key; el.textContent = t(key); }
  }
}

export function exWatchRender(): void {
  const s = session;
  if (!s || s.phase !== 'watching') return;
  /* Dòng "Đang xem" */
  const K = exMpKeys(s.kind);
  const nm = s.watched >= 0 ? (s.kind === 'walk' ? stAvatars.name(s.watched) : s.kind === 'drive' ? exDrivers.name(s.watched) : exRemotes.name(s.watched)) : null;
  const w = $('exMpWatch');
  w.hidden = nm === null;
  w.textContent = nm === null ? '' : t(K.watching, { name: '\u2068' + nm + '\u2069' });
  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
    unlock();
    if (s.notice === 'late') armLate();
  }
  if (s.notice === 'nameBad' && s.name !== rejected) {   // tên bị từ chối: quên tên đó (cả bản đã nhớ), hiện lại ô nhập để gõ tên khác
    rejected = s.name;
    if (exSanitizeName(loadName()) === rejected) saveName('');
    $<HTMLInputElement>('exMpInviteName').value = '';
  }
  let key = '';
  if (s.notice === 'late') key = performance.now() < lateUntil ? K.late : '';
  else if (s.notice === 'released') {
    const now = performance.now();
    if (!relUntil) { relUntil = now + CONFIG.explore.multi.noticeMs; clearTimeout(relTimer); relTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.noticeMs + 50); }
    key = now < relUntil ? K.released : '';
  }
  else if (s.notice === 'nameBad') key = 'exMpNameBad';
  exWatchNotice(key);
  /* Lời mời */
  const inv = $('exMpInvite'), input = $<HTMLInputElement>('exMpInviteName'), btn = $<HTMLButtonElement>('exMpInviteFly');
  inv.hidden = !s.invite;
  inviteKeys(s.kind);
  const needName = knownName() === null;
  input.hidden = !needName;
  btn.disabled = pending || (needName && exSanitizeName(input.value) === null);
}

/* Bắt đầu hiện giao diện xem cho phiên s */
export function exWatchShow(s: MultiSession): void {
  session = s; unlock(); lateUntil = 0; relUntil = 0; rejected = null;
  if (s.notice === 'late') armLate();   // bị giành chỗ ngay ở sảnh: vào xem kèm lý do
  if (!bound) {
    bound = true;
    $('exMpInviteFly').addEventListener('click', accept);
    const input = $<HTMLInputElement>('exMpInviteName');
    input.addEventListener('input', exWatchRender);
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); accept(); } });   // Esc để lọt lên trình nghe chung (thoát)
    onLang(() => { if (session) { exWatchRender(); if (noticeKey && session.phase !== 'watching') exWatchNotice(noticeKey); } });
  }
  exWatchRender();
}

/* Gỡ giao diện xem (vào bay, hoặc thoát) */
export function exWatchHide(): void {
  if (session && session.phase === 'flying') { const n = exSanitizeName(session.name); if (n !== null) saveName(n); }   // máy chủ đã nhận tên: bấy giờ mới nhớ
  session = null; unlock(); clearTimeout(lateTimer); clearTimeout(relTimer);
  $('exMpWatch').hidden = true; $('exMpInvite').hidden = true;
  exWatchNotice('');
}

/* Khi đang bay: hiện một thông báo (mất kết nối) một lần, tự ẩn sau noticeMs; đổi ngôn ngữ thì dịch lại */
export function exFlyNotice(s: MultiSession, key: string): void {
  session = s;   // để onLang dịch lại
  if (key === flyKey) return;
  flyKey = key;
  exWatchNotice(key);
  clearTimeout(flyTimer);
  if (key) flyTimer = window.setTimeout(() => { if (noticeKey === key) exWatchNotice(''); }, CONFIG.explore.multi.noticeMs);
}
/* ============================ Tự khám phá: màn chọn phương tiện ============================
   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */

import { getLang, onChange, t } from '../i18n';
import { exMulti } from './multi';
import { exShowLobby } from './multi/lobby';

export type ExChoice = 'glider' | 'guided' | 'walk' | 'car' | 'bike';   // car: lái xe (có máy chủ thì qua sảnh 5 chỗ lái, không thì lái một mình); bike: xe máy (giờ luôn lái một mình, sảnh ở Task 10)

const el = () => document.getElementById('chooser');

/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính". Thẻ Đi dạo không khóa (có điều khiển cảm ứng) */
function lockGliderOnTouch(root: HTMLElement): void {
  if (!window.matchMedia('(hover: none)').matches) return;
  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
  if (!card) return;
  card.disabled = true;
  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
}

/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
function wireLang(root: HTMLElement): void {
  const mine = root.querySelector<HTMLSelectElement>('#exLang');
  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
  if (!mine || !main) return;
  mine.innerHTML = main.innerHTML; mine.value = getLang();
  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
  onChange((code) => { mine.value = code; });
}

/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
const inerted: HTMLElement[] = [];
function setUnderInert(root: HTMLElement, on: boolean): void {
  if (on) {
    for (const c of Array.from(document.body.children) as HTMLElement[]) {
      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
      c.inert = true; inerted.push(c);
    }
  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
}

export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: (choice: ExChoice) => void = () => {}): void {
  const root = el();
  if (!root) return;
  lockGliderOnTouch(root);
  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLostChooser */
  try {
    const lost = sessionStorage.getItem('exMpNotice');   // 'lost' (xem bầu trời dù lượn) | 'lostWalk' (xem người đi dạo: câu nhắc chọn Đi dạo, vì thẻ Dù lượn bị khóa trên điện thoại) | 'lostDrive' (xem xe: nhắc chọn Ô tô)
    if (lost === 'lost' || lost === 'lostWalk' || lost === 'lostDrive') {
      sessionStorage.removeItem('exMpNotice');
      const n = document.getElementById('exMpLostNote');
      if (n) { const k = lost === 'lostWalk' ? 'stLostChooser' : lost === 'lostDrive' ? 'drLostChooser' : ''; if (k) { n.dataset.i18n = k; n.textContent = t(k); } n.hidden = false; }
    }
  } catch { /* bộ nhớ bị chặn */ }
  wireLang(root);
  /* Không dùng { once: true }: từ sảnh bấm Quay lại / Esc thì các thẻ phải chọn lại được. Hộp đã đóng (đã chọn xong) thì bỏ qua */
  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
    if (b.disabled) return;
    b.addEventListener('click', () => {
      if (root.hidden) return;
      const choice = b.dataset.pick as ExChoice;
      /* Dù lượn / Đi dạo / Ô tô có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay / đi / lái một mình ngay như trước */
      if ((choice === 'glider' || choice === 'walk' || choice === 'car') && exMulti.begin(() => {}, choice === 'walk' ? 'walk' : choice === 'car' ? 'drive' : 'fly')) {
        const solo = () => { exHideChooser(); onPick(choice); };
        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(choice); }, onSolo: solo, onBack: () => b.focus({ preventScroll: true }) });
        return;
      }
      exHideChooser(); onPick(choice);
    });
  });
  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
  const loading = document.getElementById('loading');
  if (!loading || loading.classList.contains('done')) { show(); return; }
  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
}

export function exHideChooser(): void {
  const root = el();
  if (root) { root.hidden = true; setUnderInert(root, false); }
}
/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls, renderer } from '../core/renderer';
import { composer } from '../core/postprocessing';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { plPreload, plReset, plSetWarm, plDebug } from './pilot';
import { exChase } from './chase';
import { exShowChooser } from './chooser';
import { exNight, exNightBind, exNightStep } from './nightShows';
import { exMulti } from './multi';
import { stroll, setupStroll } from './stroll';
import { drive, setupDrive } from './drive';
import { bike, setupBike } from './bike';
import { stAvatars } from './stroll/avatars';
import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
import { CONFIG } from '../config';
import type { SwingController } from '../bridges/song-han/SwingController';

const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung

/* Làm nóng shader người treo có xương (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Cảnh nguồn không thêm vào scene */
plSetWarm(async (o: THREE.Object3D) => {
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(null);
  const a = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await a;
  renderer.setRenderTarget(composer.readBuffer);
  const b = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await b;
});

let glider: THREE.Group | null = null;
let state: GliderState | null = null;
let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi

const active = () => cam.mode === 'glider' && state !== null;
const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem

/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
function watchStep(dt: number): void {
  exMulti.update(dt, performance.now(), null);
  const st = exMulti.watchState();
  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
  exNightStep(dt);
}

/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
function onMultiChange(): void {
  const s = exMulti.session; if (!s) return;
  if (watching) {
    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
    exWatchRender();
  } else if (active()) {
    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
  }
}

/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
function exShowSpeed(): void {
  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
  if (t === readout) return;
  readout = t;
  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
}

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!, dt, inp);
  exChase(camera, controls.target, state!, dt);
  exShowSpeed();
  exNightStep(dt);
  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
}

export const explore = {
  active,
  nightShows: exNight,
  get state() { return state; },
  get glider() { return glider; },
  get watching() { return watching; },
  /* Cho test: số đo người treo của dù mình (pilot/index.ts plDebug); null khi chưa bay */
  pilotDebug() { return glider ? plDebug(glider) : null; },
  start(): void {
    plPreload();
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    exMulti.onChange = onMultiChange;
    state = exCreate();
    const slot = exMulti.session ? exMulti.session.mySlot : -1;
    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    glider.visible = true;
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    plReset(glider);   // cất cánh mới: người treo không mang lò xo của lần bay trước
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    exShowSpeed();
    document.body.classList.add('explore');
  },
  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
  startWatching(carry = false): void {
    const s = exMulti.session; if (!s) return;
    plPreload();   // dù người khác dùng người treo có xương
    watching = true; chased = carry;
    keys.clear();
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    document.body.classList.add('explore', 'ex-watching');
    exMulti.onChange = onMultiChange;
    exWatchShow(s);
  },
  update(dt: number): void {
    if (watching) { watchStep(dt); return; }
    if (!active()) return;
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
    drive.stop();   // lái xe: trả hầm / lớp body / xe trước khi tải lại
    bike.stop();    // xe máy: như trên, kể cả thân va chạm
    const u = new URL(location.href);
    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
    else location.replace(u.toString());
  },
};

export function setupExplore(ctrl: SwingController): void {
  exNightBind(ctrl);
  setupStroll(ctrl, () => explore.exit());
  setupDrive(ctrl, () => explore.exit());
  setupBike(ctrl, () => explore.exit());
  window.addEventListener('keydown', (e) => {
    if (!inGlider() && !stroll.inMode() && !drive.inMode() && !bike.inMode()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe, xe máy và hai chế độ xem)
    if (watching || stroll.inMode() || drive.inMode() || bike.inMode()) return;   // xem: không lái; đi dạo / lái xe / xe máy: phím do stroll/index.ts, drive/index.ts, bike/index.ts ghi
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
  for (const id of ['langSelect', 'qualitySel']) {
    const sel = document.getElementById(id); if (!sel) continue;
    let byMouse = false;
    sel.addEventListener('pointerdown', () => { byMouse = true; });
    sel.addEventListener('keydown', () => { byMouse = false; });
    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active() || drive.active() || bike.active())) sel.blur(); byMouse = false; });
  }
  const q = new URLSearchParams(location.search);
  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
  if (q.get('explore') === 'bike') { bike.start(); return; }     // xe máy một mình
  if (!q.has('test') || q.has('chooser')) {
    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload());   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="glider"]')?.addEventListener('click', () => plPreload());   // chọn thẻ Dù lượn: nạp người treo ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
    document.querySelector('button[data-pick="bike"]')?.addEventListener('click', () => bike.preload());   // chọn thẻ Xe máy: nạp mô hình xe máy ngay (Task 3)
    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); else if (choice === 'bike') bike.start(); },
      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
  }
}
/* ===== Nhiều người: khóa chữ và số chỗ theo loại phiên (không DOM, không three) =====
   Sảnh (lobby.ts) và giao diện xem (watch.ts) dùng chung một bộ chữ cho ba loại: dù lượn (exMp*), đi dạo (st*), lái xe (dr*).
   `full` (chữ "đã đủ người") chỉ có ở đi dạo và lái xe: dù lượn đầy chỗ thì sảnh chuyển ngay sang chế độ xem. */
import { multiParams } from './params';
import type { Kind } from './protocol';

export interface ExMpKeys { sky: string; go: string; solo: string; offline: string; seats: string; full: string | null; invite: string; inviteGo: string; watching: string; late: string; released: string; lost: string }

const KEYS: Record<Kind, ExMpKeys> = {
  fly: { sky: 'exMpSky', go: 'exMpFly', solo: 'exMpSolo', offline: 'exMpOffline', seats: 'exMpSeats', full: null, invite: 'exMpInvite', inviteGo: 'exMpInviteFly', watching: 'exMpWatching', late: 'exMpLate', released: 'exMpReleased', lost: 'exMpLost' },
  walk: { sky: 'stSky', go: 'stGo', solo: 'stSolo', offline: 'stOffline', seats: 'stSeats', full: 'stFull', invite: 'stInvite', inviteGo: 'stInviteGo', watching: 'stWatch', late: 'stLate', released: 'stReleased', lost: 'stLost' },
  drive: { sky: 'stSky', go: 'drGo', solo: 'drSolo', offline: 'drOffline', seats: 'drSeats', full: 'drFull', invite: 'drInvite', inviteGo: 'drInviteGo', watching: 'drWatch', late: 'drLate', released: 'drReleased', lost: 'drLost' }
};

export const exMpKeys = (kind: Kind): ExMpKeys => KEYS[kind];

/* Số chỗ của nhóm theo loại */
export const exMpSlots = (kind: Kind): number => kind === 'walk' ? multiParams.stroll.slots : kind === 'drive' ? multiParams.drive.slots : multiParams.slots;

toolUseResult.stdout:
/* ===== Dù lượn, đi dạo và lái xe nhiều người: giao diện chế độ xem và các thông báo =====
   Chữ theo session.kind (multi/keys.ts): khóa exMp* (dù lượn), st* (đi dạo) hoặc dr* (lái xe); tên người đang xem lấy từ exRemotes, stAvatars hoặc exDrivers.
   #exMpWatch "Đang xem: tên", #exMpInvite (lời mời khi còn chỗ: ô tên nếu chưa có tên hợp lệ + nút vào bay), #exMpNotice (late / released / lost).
   late tự ẩn sau lateMs, released (khi xem) và lost (khi bay) tự ẩn sau noticeMs; nameBad giữ tới khi gõ tên khác.
   Không điều khiển camera hay phiên: explore/index.ts gọi exWatchShow / exWatchRender / exWatchHide và tự xử lý chuyển pha.
   Mọi tên người khác chỉ ghi bằng textContent, bọc trong cặp cô lập hướng chữ để tên RTL không làm lệch câu. */
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exSanitizeName } from './protocol';
import { exRemotes } from './remote';
import { stAvatars } from '../stroll/avatars';
import { exDrivers } from './remoteDrive';
import { exMpKeys } from './keys';
import type { Kind } from './protocol';
import { loadName, saveName } from './lobby';
import type { MultiSession } from './session';

const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T;

let session: MultiSession | null = null;
let bound = false;
let pending = false;       // đã bấm vào bay, chờ máy chủ trả lời: nút khóa để không gửi hai lần
let pendingTimer = 0;
let lateUntil = 0;         // mốc (ms) hết hạn hiện exMpLate
let lateTimer = 0;
let relUntil = 0;          // mốc (ms) hết hạn hiện exMpReleased; 0 = chưa hiện trong lần xem này
let relTimer = 0;
let flyKey = '';           // thông báo khi bay đã hiện (không hiện lại sau khi tự ẩn)
let flyTimer = 0;
let rejected: string | null = null;   // tên máy chủ vừa từ chối: không dùng lại, không nhớ
let noticeKey = '';        // khóa đang hiện ở #exMpNotice ('' = ẩn)

/* Tên hợp lệ đã biết: tên đã dùng trong phiên, hoặc tên nhớ ở sảnh; bỏ tên máy chủ đã từ chối */
const okName = (n: string): string | null => { const v = exSanitizeName(n); return v !== null && v !== rejected ? v : null; };
const knownName = (): string | null => (session && okName(session.name)) || okName(loadName());

/* Ghi/ẩn #exMpNotice (dùng cả khi đang bay: mất kết nối) */
export function exWatchNotice(key: string): void {
  noticeKey = key;
  const el = $('exMpNotice');
  el.textContent = key ? t(key) : '';
  el.hidden = !key;
}

function unlock(): void { pending = false; clearTimeout(pendingTimer); }

/* Hiện exMpLate thêm lateMs từ bây giờ */
function armLate(): void {
  lateUntil = performance.now() + CONFIG.explore.multi.lateMs;
  clearTimeout(lateTimer); lateTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.lateMs + 50);
}

function accept(): void {
  if (!session || session.phase !== 'watching' || pending) return;
  const input = $<HTMLInputElement>('exMpInviteName');
  const name = knownName() ?? exSanitizeName(input.value);
  if (name === null) return;
  pending = true; clearTimeout(pendingTimer);
  pendingTimer = window.setTimeout(() => { pending = false; exWatchRender(); }, CONFIG.explore.multi.pendingMs);
  session.join(name);   // join xóa notice cũ trước khi vẽ lại, nếu không nameBad cũ sẽ mở khóa nút ngay
  exWatchRender();
}

/* Lời mời: ghi chữ theo loại và nhớ khóa ở data-i18n để đổi ngôn ngữ dịch đúng */
function inviteKeys(kind: Kind): void {
  const K = exMpKeys(kind);
  for (const [id, key] of [['exMpInviteText', K.invite], ['exMpInviteFly', K.inviteGo]]) {
    const el = $(id);
    if (el.dataset.i18n !== key) { el.dataset.i18n = key; el.textContent = t(key); }
  }
}

export function exWatchRender(): void {
  const s = session;
  if (!s || s.phase !== 'watching') return;
  /* Dòng "Đang xem" */
  const K = exMpKeys(s.kind);
  const nm = s.watched >= 0 ? (s.kind === 'walk' ? stAvatars.name(s.watched) : s.kind === 'drive' ? exDrivers.name(s.watched) : exRemotes.name(s.watched)) : null;
  const w = $('exMpWatch');
  w.hidden = nm === null;
  w.textContent = nm === null ? '' : t(K.watching, { name: '\u2068' + nm + '\u2069' });
  /* Thông báo từ phiên: nút đã có trả lời thì mở khóa */
  if (pending && (s.notice === 'late' || s.notice === 'nameBad')) {
    unlock();
    if (s.notice === 'late') armLate();
  }
  if (s.notice === 'nameBad' && s.name !== rejected) {   // tên bị từ chối: quên tên đó (cả bản đã nhớ), hiện lại ô nhập để gõ tên khác
    rejected = s.name;
    if (exSanitizeName(loadName()) === rejected) saveName('');
    $<HTMLInputElement>('exMpInviteName').value = '';
  }
  let key = '';
  if (s.notice === 'late') key = performance.now() < lateUntil ? K.late : '';
  else if (s.notice === 'released') {
    const now = performance.now();
    if (!relUntil) { relUntil = now + CONFIG.explore.multi.noticeMs; clearTimeout(relTimer); relTimer = window.setTimeout(exWatchRender, CONFIG.explore.multi.noticeMs + 50); }
    key = now < relUntil ? K.released : '';
  }
  else if (s.notice === 'nameBad') key = 'exMpNameBad';
  exWatchNotice(key);
  /* Lời mời */
  const inv = $('exMpInvite'), input = $<HTMLInputElement>('exMpInviteName'), btn = $<HTMLButtonElement>('exMpInviteFly');
  inv.hidden = !s.invite;
  inviteKeys(s.kind);
  const needName = knownName() === null;
  input.hidden = !needName;
  btn.disabled = pending || (needName && exSanitizeName(input.value) === null);
}

/* Bắt đầu hiện giao diện xem cho phiên s */
export function exWatchShow(s: MultiSession): void {
  session = s; unlock(); lateUntil = 0; relUntil = 0; rejected = null;
  if (s.notice === 'late') armLate();   // bị giành chỗ ngay ở sảnh: vào xem kèm lý do
  if (!bound) {
    bound = true;
    $('exMpInviteFly').addEventListener('click', accept);
    const input = $<HTMLInputElement>('exMpInviteName');
    input.addEventListener('input', exWatchRender);
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); accept(); } });   // Esc để lọt lên trình nghe chung (thoát)
    onLang(() => { if (session) { exWatchRender(); if (noticeKey && session.phase !== 'watching') exWatchNotice(noticeKey); } });
  }
  exWatchRender();
}

/* Gỡ giao diện xem (vào bay, hoặc thoát) */
export function exWatchHide(): void {
  if (session && session.phase === 'flying') { const n = exSanitizeName(session.name); if (n !== null) saveName(n); }   // máy chủ đã nhận tên: bấy giờ mới nhớ
  session = null; unlock(); clearTimeout(lateTimer); clearTimeout(relTimer);
  $('exMpWatch').hidden = true; $('exMpInvite').hidden = true;
  exWatchNotice('');
}

/* Khi đang bay: hiện một thông báo (mất kết nối) một lần, tự ẩn sau noticeMs; đổi ngôn ngữ thì dịch lại */
export function exFlyNotice(s: MultiSession, key: string): void {
  session = s;   // để onLang dịch lại
  if (key === flyKey) return;
  flyKey = key;
  exWatchNotice(key);
  clearTimeout(flyTimer);
  if (key) flyTimer = window.setTimeout(() => { if (noticeKey === key) exWatchNotice(''); }, CONFIG.explore.multi.noticeMs);
}
/* ============================ Tự khám phá: màn chọn phương tiện ============================
   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */

import { getLang, onChange, t } from '../i18n';
import { exMulti } from './multi';
import { exShowLobby } from './multi/lobby';

export type ExChoice = 'glider' | 'guided' | 'walk' | 'car' | 'bike';   // car: lái xe (có máy chủ thì qua sảnh 5 chỗ lái, không thì lái một mình); bike: xe máy (giờ luôn lái một mình, sảnh ở Task 10)

const el = () => document.getElementById('chooser');

/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính". Thẻ Đi dạo không khóa (có điều khiển cảm ứng) */
function lockGliderOnTouch(root: HTMLElement): void {
  if (!window.matchMedia('(hover: none)').matches) return;
  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
  if (!card) return;
  card.disabled = true;
  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
}

/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
function wireLang(root: HTMLElement): void {
  const mine = root.querySelector<HTMLSelectElement>('#exLang');
  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
  if (!mine || !main) return;
  mine.innerHTML = main.innerHTML; mine.value = getLang();
  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
  onChange((code) => { mine.value = code; });
}

/* Màn chọn là hộp thoại modal: các khối giao diện cũ (header, panel, canvas...) đặt inert để Tab/Enter không lọt xuống dưới */
const inerted: HTMLElement[] = [];
function setUnderInert(root: HTMLElement, on: boolean): void {
  if (on) {
    for (const c of Array.from(document.body.children) as HTMLElement[]) {
      if (c === root || c.tagName === 'SCRIPT' || c.id === 'loading' || c.inert) continue;
      c.inert = true; inerted.push(c);
    }
  } else { for (const c of inerted) c.inert = false; inerted.length = 0; }
}

export function exShowChooser(onPick: (choice: ExChoice) => void, onWatch: (choice: ExChoice) => void = () => {}): void {
  const root = el();
  if (!root) return;
  lockGliderOnTouch(root);
  /* Lần trước mất kết nối khi đang xem (explore.exit tải lại trang): đọc cờ một lần rồi xóa, hiện exMpLostChooser */
  try {
    const lost = sessionStorage.getItem('exMpNotice');   // 'lost' (xem bầu trời dù lượn) | 'lostWalk' (xem người đi dạo: câu nhắc chọn Đi dạo, vì thẻ Dù lượn bị khóa trên điện thoại) | 'lostDrive' (xem xe: nhắc chọn Ô tô)
    if (lost === 'lost' || lost === 'lostWalk' || lost === 'lostDrive') {
      sessionStorage.removeItem('exMpNotice');
      const n = document.getElementById('exMpLostNote');
      if (n) { const k = lost === 'lostWalk' ? 'stLostChooser' : lost === 'lostDrive' ? 'drLostChooser' : ''; if (k) { n.dataset.i18n = k; n.textContent = t(k); } n.hidden = false; }
    }
  } catch { /* bộ nhớ bị chặn */ }
  wireLang(root);
  /* Không dùng { once: true }: từ sảnh bấm Quay lại / Esc thì các thẻ phải chọn lại được. Hộp đã đóng (đã chọn xong) thì bỏ qua */
  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
    if (b.disabled) return;
    b.addEventListener('click', () => {
      if (root.hidden) return;
      const choice = b.dataset.pick as ExChoice;
      /* Dù lượn / Đi dạo / Ô tô có máy chủ: sang bước chọn slot + nhập tên (mở kết nối ở đây, không sớm hơn); không có máy chủ: bay / đi / lái một mình ngay như trước */
      if ((choice === 'glider' || choice === 'walk' || choice === 'car') && exMulti.begin(() => {}, choice === 'walk' ? 'walk' : choice === 'car' ? 'drive' : 'fly')) {
        const solo = () => { exHideChooser(); onPick(choice); };
        exShowLobby(exMulti.session!, { onFly: solo, onWatch: () => { exHideChooser(); onWatch(choice); }, onSolo: solo, onBack: () => b.focus({ preventScroll: true }) });
        return;
      }
      exHideChooser(); onPick(choice);
    });
  });
  const show = () => { root.hidden = false; setUnderInert(root, true); root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
  const loading = document.getElementById('loading');
  if (!loading || loading.classList.contains('done')) { show(); return; }
  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
}

export function exHideChooser(): void {
  const root = el();
  if (root) { root.hidden = true; setUnderInert(root, false); }
}
/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls, renderer } from '../core/renderer';
import { composer } from '../core/postprocessing';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { plPreload, plReset, plSetWarm, plDebug } from './pilot';
import { exChase } from './chase';
import { exShowChooser } from './chooser';
import { exNight, exNightBind, exNightStep } from './nightShows';
import { exMulti } from './multi';
import { stroll, setupStroll } from './stroll';
import { drive, setupDrive } from './drive';
import { bike, setupBike } from './bike';
import { stAvatars } from './stroll/avatars';
import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from './multi/watch';
import { CONFIG } from '../config';
import type { SwingController } from '../bridges/song-han/SwingController';

const _inp: GliderInput = { turn: 0, climb: 0, throttle: 0 };   // đầu vào tái dùng mỗi khung

/* Làm nóng shader người treo có xương (D-018), như stroll/index.ts stRigSetWarm: hai biến thể (vẽ thẳng ra canvas ban ngày, vào render target của composer ban đêm),
   đèn / sương / bóng lấy từ cảnh chính, camera chính (đèn lọc theo lớp của nó). Cảnh nguồn không thêm vào scene */
plSetWarm(async (o: THREE.Object3D) => {
  const rt = renderer.getRenderTarget();
  renderer.setRenderTarget(null);
  const a = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await a;
  renderer.setRenderTarget(composer.readBuffer);
  const b = renderer.compileAsync(o, camera, scene);
  renderer.setRenderTarget(rt);
  await b;
});

let glider: THREE.Group | null = null;
let state: GliderState | null = null;
let watching = false;   // đang xem người khác bay (hết chỗ hoặc vừa nhường chỗ): không có dù của mình, không đọc phím
let chased = false;     // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
let readout = '';   // chữ đang hiện ở #exSpeed: chỉ ghi DOM khi đổi

const active = () => cam.mode === 'glider' && state !== null;
const inGlider = () => active() || watching;   // Esc và giao diện bay áp cho cả chế độ xem

/* Mỗi khung khi xem: dù người khác, nhãn, danh sách; camera bám dù đang xem (không có người thì giữ nguyên) */
function watchStep(dt: number): void {
  exMulti.update(dt, performance.now(), null);
  const st = exMulti.watchState();
  if (st) { exChase(camera, controls.target, st, dt, !chased); chased = true; }
  exNightStep(dt);
}

/* Đổi phiên khi đang xem hoặc bay: vào bay, mất kết nối, bị thu hồi chỗ */
function onMultiChange(): void {
  const s = exMulti.session; if (!s) return;
  if (watching) {
    if (s.phase === 'flying') { explore.start(); return; }   // chấp nhận lời mời: cất cánh mới như bay thường
    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } explore.exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
    exWatchRender();
  } else if (active()) {
    if (s.phase === 'watching') { state = null; if (glider) glider.visible = false; explore.startWatching(true); return; }   // chỗ bị thu hồi: sang xem, camera giữ nguyên
    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'exMpLost');   // vẫn bay, người khác đã biến mất
  }
}

/* Đồng hồ tốc độ (km/h) và độ cao (m): chỉ số và đơn vị nên không cần dịch */
function exShowSpeed(): void {
  const t = `${Math.round(state!.speed * 3.6)} km/h · ${Math.round(state!.pos.y)} m`;
  if (t === readout) return;
  readout = t;
  const el = document.getElementById('exSpeed'); if (el) el.textContent = t;
}

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!, dt, inp);
  exChase(camera, controls.target, state!, dt);
  exShowSpeed();
  exNightStep(dt);
  exMulti.update(dt, performance.now(), state);   // dù người khác, nhãn tên, gửi vị trí (không làm gì khi bay một mình)
}

export const explore = {
  active,
  nightShows: exNight,
  get state() { return state; },
  get glider() { return glider; },
  get watching() { return watching; },
  /* Cho test: số đo người treo của dù mình (pilot/index.ts plDebug); null khi chưa bay */
  pilotDebug() { return glider ? plDebug(glider) : null; },
  start(): void {
    plPreload();
    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
    exMulti.onChange = onMultiChange;
    state = exCreate();
    const slot = exMulti.session ? exMulti.session.mySlot : -1;
    if (slot >= 0) state.pos.z += CONFIG.explore.multi.spawnSpread * (slot - 2);   // mỗi slot cất cánh lệch một đoạn để không chồng nhau
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    glider.visible = true;
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    plReset(glider);   // cất cánh mới: người treo không mang lò xo của lần bay trước
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    exShowSpeed();
    document.body.classList.add('explore');
  },
  /* Chế độ xem: cam.mode = 'glider' nhưng không có state/dù của mình; carry = true khi vừa nhường chỗ (camera đang ở sau dù cũ) */
  startWatching(carry = false): void {
    const s = exMulti.session; if (!s) return;
    plPreload();   // dù người khác dùng người treo có xương
    watching = true; chased = carry;
    keys.clear();
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    document.body.classList.add('explore', 'ex-watching');
    exMulti.onChange = onMultiChange;
    exWatchShow(s);
  },
  update(dt: number): void {
    if (watching) { watchStep(dt); return; }
    if (!active()) return;
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
    drive.stop();   // lái xe: trả hầm / lớp body / xe trước khi tải lại
    bike.stop();    // xe máy: như trên, kể cả thân va chạm
    const u = new URL(location.href);
    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
    if (u.href === location.href) location.reload();   // URL chỉ khác phần #ngôn-ngữ: replace chỉ là điều hướng fragment, không tải lại
    else location.replace(u.toString());
  },
};

export function setupExplore(ctrl: SwingController): void {
  exNightBind(ctrl);
  setupStroll(ctrl, () => explore.exit());
  setupDrive(ctrl, () => explore.exit());
  setupBike(ctrl, () => explore.exit());
  window.addEventListener('keydown', (e) => {
    if (!inGlider() && !stroll.inMode() && !drive.inMode() && !bike.inMode()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn (bay dù, đi dạo, lái xe, xe máy và hai chế độ xem)
    if (watching || stroll.inMode() || drive.inMode() || bike.inMode()) return;   // xem: không lái; đi dạo / lái xe / xe máy: phím do stroll/index.ts, drive/index.ts, bike/index.ts ghi
    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt (Cmd+S...) không lái dù, tránh kẹt phím
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  /* Chọn ngôn ngữ / chất lượng bằng chuột xong thì bỏ focus, nếu không mũi tên và WASD sau đó đổi cài đặt thay vì lái dù. Dùng Tab + bàn phím thì giữ nguyên. */
  for (const id of ['langSelect', 'qualitySel']) {
    const sel = document.getElementById(id); if (!sel) continue;
    let byMouse = false;
    sel.addEventListener('pointerdown', () => { byMouse = true; });
    sel.addEventListener('keydown', () => { byMouse = false; });
    sel.addEventListener('change', () => { if (byMouse && (active() || stroll.active() || drive.active() || bike.active())) sel.blur(); byMouse = false; });
  }
  const q = new URLSearchParams(location.search);
  exNight.enabled = !q.has('test');   // test bật tường minh qua __app.explore.nightShows
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (q.get('explore') === 'stroll') { stroll.start(); return; }   // đi dạo một mình, không qua slot
  if (q.get('explore') === 'drive') { drive.start(); return; }   // lái xe một mình
  if (q.get('explore') === 'bike') { bike.start(); return; }     // xe máy một mình
  if (!q.has('test') || q.has('chooser')) {
    document.querySelector('button[data-pick="walk"]')?.addEventListener('click', () => stAvatars.preload());   // chọn thẻ Đi dạo: nạp nhân vật của mình ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="glider"]')?.addEventListener('click', () => plPreload());   // chọn thẻ Dù lượn: nạp người treo ngay, trong lúc ở sảnh
    document.querySelector('button[data-pick="car"]')?.addEventListener('click', () => drive.preload());   // chọn thẻ Ô tô: nạp mô hình xe ngay
    document.querySelector('button[data-pick="bike"]')?.addEventListener('click', () => bike.preload());   // chọn thẻ Xe máy: nạp mô hình xe máy ngay (Task 3)
    exShowChooser((choice) => { if (choice === 'glider') explore.start(); else if (choice === 'walk') stroll.start(); else if (choice === 'car') drive.start(); else if (choice === 'bike') bike.start(); },
      (choice) => { if (choice === 'walk') stroll.startWatching(); else if (choice === 'car') drive.startWatching(); else explore.startWatching(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
  }
}
/* ===== Nhiều người: khóa chữ và số chỗ theo loại phiên (không DOM, không three) =====
   Sảnh (lobby.ts) và giao diện xem (watch.ts) dùng chung một bộ chữ cho ba loại: dù lượn (exMp*), đi dạo (st*), lái xe (dr*).
   `full` (chữ "đã đủ người") chỉ có ở đi dạo và lái xe: dù lượn đầy chỗ thì sảnh chuyển ngay sang chế độ xem. */
import { multiParams } from './params';
import type { Kind } from './protocol';

export interface ExMpKeys { sky: string; go: string; solo: string; offline: string; seats: string; full: string | null; invite: string; inviteGo: string; watching: string; late: string; released: string; lost: string }

const KEYS: Record<Kind, ExMpKeys> = {
  fly: { sky: 'exMpSky', go: 'exMpFly', solo: 'exMpSolo', offline: 'exMpOffline', seats: 'exMpSeats', full: null, invite: 'exMpInvite', inviteGo: 'exMpInviteFly', watching: 'exMpWatching', late: 'exMpLate', released: 'exMpReleased', lost: 'exMpLost' },
  walk: { sky: 'stSky', go: 'stGo', solo: 'stSolo', offline: 'stOffline', seats: 'stSeats', full: 'stFull', invite: 'stInvite', inviteGo: 'stInviteGo', watching: 'stWatch', late: 'stLate', released: 'stReleased', lost: 'stLost' },
  drive: { sky: 'stSky', go: 'drGo', solo: 'drSolo', offline: 'drOffline', seats: 'drSeats', full: 'drFull', invite: 'drInvite', inviteGo: 'drInviteGo', watching: 'drWatch', late: 'drLate', released: 'drReleased', lost: 'drLost' }
};

export const exMpKeys = (kind: Kind): ExMpKeys => KEYS[kind];

/* Số chỗ của nhóm theo loại */
export const exMpSlots = (kind: Kind): number => kind === 'walk' ? multiParams.stroll.slots : kind === 'drive' ? multiParams.drive.slots : multiParams.slots;

