export interface BkRiderSig { lean: number; acc: number; susF: number; susR: number; steer: number }   // lean rad (trái +), acc m/s² gia tốc dọc, susF / susR m lún giảm xóc, steer rad (trái +)

const RC = CONFIG.bike.rider;
