"""   Sảnh đi dạo có thêm ô chọn nhân vật nam / nữ (#stCharPick, cả khi ngoại tuyến): nhớ ở stChar, ghi vào session.ch để join gửi kèm, nạp trước mô hình vừa chọn.
   Sảnh lái dùng chung cho ô tô và xe máy (5 chỗ chung, D-040): danh sách ghi 🚗 / 🛵 theo veh; phiên xe máy (session.veh = 1) cũng có #stCharPick (người lái, chung stChar với Đi dạo).""")
f.rep("""import { exMulti } from './index';""","""import { exMulti, exVehIcon } from './index';""")
f.rep("""import { stAvatars } from '../stroll/avatars';""","""import { stAvatars } from '../stroll/avatars';
import { bkRiderLoad } from '../bike/rider';""")
f.rep("""const M = CONFIG.explore.multi;""","""const M = CONFIG.explore.multi;
const charPick = (s: MultiSession): boolean => s.kind === 'walk' || (s.kind === 'drive' && s.veh === 1);   // sảnh có chọn nhân vật: đi dạo, xe máy""")
f.rep("""  /* Chọn nhân vật: chỉ sảnh đi dạo; hiện cả khi ngoại tuyến (đi một mình vẫn theo nhân vật đã chọn) */
  const pick = $('stCharPick'), ch = stChar.get();
  pick.hidden = session.kind !== 'walk';""","""  /* Chọn nhân vật: sảnh đi dạo và sảnh xe máy; hiện cả khi ngoại tuyến (đi / lái một mình vẫn theo nhân vật đã chọn) */
  const pick = $('stCharPick'), ch = stChar.get();
  pick.hidden = !charPick(session);""")
f.rep("""  const key = session.kind + '#' + peers.map(f => f.slot + ':' + f.name).join('|');""","""  const drive = session.kind === 'drive';
  const key = session.kind + '#' + peers.map(f => f.slot + ':' + (drive ? exVehIcon(f.veh) : '') + f.name).join('|');""")
f.rep("""      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
      row.append(dot, nm); list.appendChild(row);""","""      const nm = document.createElement('span'); nm.textContent = f.name; nm.dir = 'auto';
      if (drive) { const ic = document.createElement('span'); ic.textContent = exVehIcon(f.veh); ic.setAttribute('aria-hidden', 'true'); row.append(dot, ic, nm); }   // biểu tượng tách khỏi tên (tên RTL không kéo lệch)
      else row.append(dot, nm);
      list.appendChild(row);""")
f.rep("""/* Đổi nhân vật ở sảnh: nhớ, đưa vào phiên (join gửi kèm), nạp trước mô hình */
function pickChar(ch: number): void {
  if (!cur || cur.session.kind !== 'walk') return;
  stChar.set(ch); cur.session.ch = stChar.get();
  stAvatars.preload();""","""/* Đổi nhân vật ở sảnh: nhớ, đưa vào phiên (join gửi kèm), nạp trước mô hình (người đi dạo, hoặc người lái xe máy) */
function pickChar(ch: number): void {
  if (!cur || !charPick(cur.session)) return;
  stChar.set(ch); cur.session.ch = stChar.get();
  if (cur.session.kind === 'walk') stAvatars.preload(); else void bkRiderLoad(cur.session.ch);""")
f.rep("""  if (session.kind === 'walk') session.ch = stChar.get();
  exMulti.onChange = render;""","""  if (charPick(session)) session.ch = stChar.get();
  exMulti.onChange = render;""")
f.save()

