from edlib import F
f = F('src/explore/chooser.ts')
f.rep("""export type ExChoice = 'glider' | 'guided' | 'walk' | 'car' | 'bike';   // car: lái xe (có máy chủ thì qua sảnh 5 chỗ lái, không thì lái một mình); bike: xe máy (giờ luôn lái một mình, sảnh ở Task 10)""",
"""export type ExChoice = 'glider' | 'guided' | 'walk' | 'car' | 'bike';   // car: lái xe (có máy chủ thì qua sảnh 5 chỗ lái, không thì lái một mình); bike: xe máy (chung sảnh 5 chỗ lái với ô tô, phiên 'drive' veh 1)""")
f.rep("""    const lost = sessionStorage.getItem('exMpNotice');   // 'lost' (xem bầu trời dù lượn) | 'lostWalk' (xem người đi dạo: câu nhắc chọn Đi dạo, vì thẻ Dù lượn bị khóa trên điện thoại) | 'lostDrive' (xem xe: nhắc chọn Ô tô)
    if (lost === 'lost' || lost === 'lostWalk' || lost === 'lostDrive') {
      sessionStorage.removeItem('exMpNotice');
