const W = 2 * Math.PI * C1.hz;
const fin = (v: number): number => (Number.isFinite(v) ? v : 0);
const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v);

/* Mắt trong hệ thân xe: đo từ người lái (bkCamSetEye) hoặc cam1.eye */
