  c.yaw = clamp(c.yaw - fin(dx) * C1.mouse, -C1.yawMax, C1.yawMax);
  c.pitch = clamp(c.pitch - fin(dy) * C1.mouse, C1.pitchMin, C1.pitchMax);
  c.idle = 0;
}
